components.css:
.ds-primary {min-height:60px;
    width:100%;
    display:flex;
    align-items:center;
    justify-content:center;
    gap:12px;
    border:0;
    border-radius:12px;
    background:var(--accent,#ffc49d);
    color:#47301d;
    font-size:19px;
    font-weight:800;
    box-shadow:0 5px 12px #947b6340;
    transition:background .18s,transform .18s,box-shadow .18s;}.ds-primary {font-family:-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;cursor:pointer;}.ds-primary:hover:not(:disabled) {background:#ffd5b8;}.ds-primary:active:not(:disabled) {transform:translateY(4px);
    box-shadow:0 2px 5px #947b632e;}.ds-primary:disabled {cursor:wait;
    opacity:.55;}.ds-primary:focus-visible,.ds-clear:focus-visible,.ds-nav a:focus-visible,.ds-choice:focus-visible {outline:3px solid #bb4e27;outline-offset:5px;}@media(prefers-reduced-motion:reduce){.ds-primary{transition:none;}}

.ds-clear {min-height:44px;
    padding:8px 0 8px 12px;
    border:0;
    background:transparent;
    color:var(--muted,#546e68);
    font-size:13px;}.ds-clear {font-family:-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;cursor:pointer;}.ds-clear:hover {color:#9b3e16;}.ds-primary:focus-visible,.ds-clear:focus-visible,.ds-nav a:focus-visible,.ds-choice:focus-visible {outline:3px solid #bb4e27;outline-offset:5px;}

.ds-nav {display:flex;
    gap:4px;
    padding:5px;
    background:#dbe6df;
    border-radius:12px;}.ds-nav {font-family:-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;}.ds-nav a {min-height:44px;
    display:flex;
    align-items:center;
    justify-content:center;
    padding:0 20px;
    border-radius:8px;
    text-decoration:none;
    color:#385b52;
    font-size:14px;
    font-weight:650;}.ds-nav .ds-current {background:var(--ink,#183f3a);
    color:var(--white,#fffef7);}.ds-nav a:hover:not(.ds-current) {background:#ccdcd2;}.ds-primary:focus-visible,.ds-clear:focus-visible,.ds-nav a:focus-visible,.ds-choice:focus-visible {outline:3px solid #bb4e27;outline-offset:5px;}

.ds-choices {display:flex;
    gap:5px;
    background:#dbe6df;
    padding:4px;
    border-radius:10px;}.ds-choice {min-width:44px;
    min-height:44px;
    padding:8px 13px;
    border:0;
    border-radius:7px;
    background:transparent;
    color:var(--ink,#183f3a);
    font-size:14px;
    font-weight:650;}.ds-choice {font-family:-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;cursor:pointer;}.ds-choice.ds-selected {background:var(--ink,#183f3a);
    color:var(--white,#fffef7);}.ds-primary:focus-visible,.ds-clear:focus-visible,.ds-nav a:focus-visible,.ds-choice:focus-visible {outline:3px solid #bb4e27;outline-offset:5px;}

.ds-field {position:relative;
    background:var(--table,#18594f);
    border-radius:16px;
    min-height:470px;
    overflow:hidden;
    color:var(--white,#fffef7);
    display:flex;
    flex-direction:column;
    align-items:center;
    padding:32px 20px 24px;}.ds-field {font-family:-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;}.ds-field::after {content:'';
    position:absolute;
    inset:14px;
    border:1px solid #508477;
    border-radius:9px;
    pointer-events:none;}.ds-result {font-size:64px;
    font-weight:800;
    line-height:1.08;
    letter-spacing:-.04em;
    color:var(--white,#fffef7);}.ds-caption {color:#d1e6db;
    font-size:12px;
    position:relative;
    z-index:1;
    line-height:1.6;
    text-align:center;}
